data.auto-generated-captions-english-only#Aut:
Mux uses OpenAI's Whisper model to automatically generate captions for your audios - read more.Unbody stores these captions as SubtitleFile and SubtitleEntry objects, here's how you can retrieve them:
query {
  Get {
    SubtitleFile(
      where: {
        operator: Equal
        path: ["media", "AudioFile", "originalName"]
        valueText: "your-audio-file.mp3"
      }
    ) {
      entries {
        ... on SubtitleEntry {
          start
          end
          text
        }
      }
    }
  }
}
import { Unbody } from "@unbody-io/ts-client";
const unbody = new Unbody({
  apiKey: "your-api-key",
  projectId: "your-project-id",
});
const {
  data: { payload: subtitleFiles },
} = await unbody.get.subtitleFile
  .where({
    media: {
      AudioFile: {
        originalName: "your-audio-file.mp3",
      },
    },
  })
  .select(
    "entries.SubtitleEntry.start",
    "entries.SubtitleEntry.end",
    "entries.SubtitleEntry.text"
  )
  .exec();
const { entries } = subtitleFiles[0];
